15	@Repository
16	public class SealInspectionRepository {
17	
18	    private static final InspectionRowMapper ROW_MAPPER = new InspectionRowMapper();
19	
20	    private final JdbcTemplate jdbc;
21	
22	    public SealInspectionRepository(JdbcTemplate jdbc) {
23	        this.jdbc = jdbc;
