28	     */
29	    public void insert(String evidenceKey, String inspectorId, boolean passed, String note,
30	                       LocalDateTime now) {
31	        jdbc.update("""
32	                        INSERT INTO seal_inspection
33	                            (evidence_key, inspector_id, passed, note, created_at)
34	                        VALUES (?, ?, ?, ?, ?)
35	                        """,
36	                evidenceKey, inspectorId, passed ? 1 : 0, note, now);
37	    }
