39	    /**
40	     * 按发生顺序查询证物全部核验记录。
41	     */
42	    public List<SealInspection> findByEvidenceKey(String evidenceKey) {
43	        return jdbc.query(
44	                "SELECT * FROM seal_inspection WHERE evidence_key = ? ORDER BY id",
45	                ROW_MAPPER, evidenceKey);
46	    }
